entries[10713] = { ["name"] = "Pläne: Veredelter Mithrilzylinder", ["text"] = "Benötigt Schmiedekunst (200)\nBenutzen: Lehrt Euch die Herstellung eines veredelten Mithrilzylinders. Dieser Gegenstand wird von Gnomen-Ingenieuren verwendet.\nVeredelter Mithrilzylinder\n\"Wird von Gnomen-Ingenieuren verwendet, um ihre Erfindungen zu verstärken.\"\nBenötigt Mithrilbarren (5), Goldbarren , Echtsilberbarren" }
